window.AI_CURRICULUM_9 = [{"id":"aireflectionethics9","index":0,"name":"AI Reflection, Project Cycle and Ethics","subtitle":"Artificial Intelligence — Unit 1","emoji":"🧭","palette":{"from":"#38bdf8","to":"#0c4a6e"},"lessons":[{"id":"pc1","title":"The Three Realms of AI","icon":"🔭","kind":"lesson","story":"You step into the AI Observatory, where three glowing towers hum with different kinds of intelligence. To become a Study Atlas Ranger, you must learn what each tower can do.","teach":[{"title":"Data & Statistics","body":"This domain of AI works with numbers, spreadsheets, and patterns — like predicting weather from past temperatures or guessing your next move in Rock-Paper-Scissors from your previous choices.","visual":"📈"},{"title":"Computer Vision (CV)","body":"Computer Vision lets machines \"see\" and make sense of images and videos — recognizing a sketch, spotting a face, or reading a sign.","visual":"👁️"},{"title":"Natural Language Processing (NLP)","body":"NLP helps machines understand, respond to, and generate human language — used in chatbots, voice assistants, and word-guessing games.","visual":"💬"},{"title":"One Problem, Many Domains","body":"Real AI problems often need more than one domain working together — for example, a voice assistant that hears you (NLP) and also recognizes objects around you (CV).","visual":"🧠"}],"questions":[{"kind":"mcq","prompt":"A game where the AI must guess a word from your typed clues belongs to which AI domain?","options":["Data & Statistics","Computer Vision","Robotics","Natural Language Processing"],"answer":3,"explain":"Understanding and responding to words and language is the job of NLP."},{"kind":"mcq","prompt":"An app that identifies a bird species from a photograph is mainly using...","options":["Computer Vision","Natural Language Processing","Data & Statistics","None of these"],"answer":0,"explain":"Recognizing something within an image is a Computer Vision task."},{"kind":"mcq","prompt":"An AI that studies years of rainfall numbers to predict next month's rainfall relies mainly on...","options":["Data & Statistics","Computer Vision","Ethics","Natural Language Processing"],"answer":0,"explain":"Working with numeric records and patterns over time is Data & Statistics."},{"kind":"mcq","prompt":"Which of these is NOT one of the three AI domains covered in this unit?","options":["Natural Language Processing","Computer Vision","Robotics","Data & Statistics"],"answer":2,"explain":"This unit focuses on Data & Statistics, Computer Vision, and NLP — Robotics is a different field."}]},{"id":"pc2","title":"Mapping the AI Project Cycle","icon":"🔄","kind":"lesson","story":"Deep in the observatory's control room lies a six-gear machine. Each gear must turn in the right order for an AI project to work. Learn the gears, adventurer.","teach":[{"title":"The AI Project Cycle","body":"The AI Project Cycle is a step-by-step framework that guides how any AI project is built, from spotting a problem to actually using the solution.","visual":"🗺️"},{"title":"The Six Stages","body":"In order, the stages are: Problem Scoping, Data Acquisition, Data Exploration, Modeling, Evaluation, and Deployment.","visual":"6️⃣"},{"title":"It's a Cycle, Not a Line","body":"Real projects often loop back — for example, poor results in Evaluation might send you back to collect better data in Data Acquisition.","visual":"🔁"}],"questions":[{"kind":"numeric","prompt":"How many stages make up the AI Project Cycle?","answer":6,"explain":"Problem Scoping, Data Acquisition, Data Exploration, Modeling, Evaluation, Deployment — six stages in total."},{"kind":"mcq","prompt":"Which stage of the AI Project Cycle comes FIRST?","options":["Data Acquisition","Problem Scoping","Deployment","Modeling"],"answer":1,"explain":"Every AI project begins by clearly scoping the problem before collecting any data."},{"kind":"mcq","prompt":"Which stage comes right AFTER Data Exploration?","options":["Data Acquisition","Problem Scoping","Modeling","Deployment"],"answer":2,"explain":"Once the data is explored and visualised, it is used to build the model in the Modeling stage."},{"kind":"mcq","prompt":"Which stage comes LAST, when the AI solution is finally put to real use?","options":["Deployment","Evaluation","Problem Scoping","Data Acquisition"],"answer":0,"explain":"Deployment is when the finished AI solution is released for real-world use."}]},{"id":"pc3","title":"Problem Scoping & the 4Ws Canvas","icon":"🧩","kind":"lesson","story":"A locked gate shows four empty windows: Who, What, Where, Why. Fill each one honestly to unlock the path toward your AI project's goal.","teach":[{"title":"Who","body":"The 'Who' identifies the stakeholders — the people who face the problem, such as students struggling with a subject or commuters stuck in traffic.","visual":"🧑‍🤝‍🧑"},{"title":"What","body":"The 'What' names the problem itself, along with evidence that it truly exists, like survey data or news reports about the issue.","visual":"❓"},{"title":"Where","body":"The 'Where' describes the context or situation in which the problem occurs — the place, condition, or circumstances surrounding it.","visual":"📍"},{"title":"Why","body":"The 'Why' explains the benefits of solving the problem — why it is worth the effort, and what improves once a solution exists.","visual":"🎯"}],"questions":[{"kind":"mcq","prompt":"In the 4Ws canvas, which 'W' is about the people affected by the problem?","options":["Why","What","Where","Who"],"answer":3,"explain":"'Who' identifies the stakeholders facing the problem."},{"kind":"mcq","prompt":"'This problem happens mostly during morning rush hour on Route 9' best fits which 'W'?","options":["Why","Where","What","Who"],"answer":1,"explain":"This describes the context/situation, which is the 'Where'."},{"kind":"mcq","prompt":"'Solving this will save commuters 30 minutes daily' is an answer to which 'W'?","options":["What","Why","Where","Who"],"answer":1,"explain":"'Why' captures the benefit of solving the problem."},{"kind":"mcq","prompt":"The 4Ws canvas is used during which stage of the AI Project Cycle?","options":["Evaluation","Data Acquisition","Problem Scoping","Deployment"],"answer":2,"explain":"The 4Ws canvas is a tool used to scope out and understand the problem."}]},{"id":"pc4","title":"Stakeholders & Early Ethics","icon":"🤝","kind":"lesson","story":"Before you chase a solution, the Council of Stakeholders demands to be heard. Who stands to gain, who stands to lose, and is your plan fair to all of them?","teach":[{"title":"Who are Stakeholders?","body":"Stakeholders are all the people connected to or affected by a problem — for a road-safety AI project, that could include drivers, pedestrians, traffic police, and the local government.","visual":"👥"},{"title":"Why Identify Them Early?","body":"Listing stakeholders helps you understand different points of view and design an AI solution that actually helps the people who need it.","visual":"🔍"},{"title":"Thinking About Ethics Early","body":"While scoping a problem, it's important to brainstorm the ethical issues too — such as privacy or fairness — so they aren't ignored later.","visual":"⚖️"}],"questions":[{"kind":"mcq","prompt":"For an AI project that recommends study plans to students, which of these is a stakeholder?","options":["Teachers","The weather","A random stranger","None of these"],"answer":0,"explain":"Teachers are directly involved with and affected by student study plans, making them a stakeholder."},{"kind":"mcq","prompt":"Why should a project team list stakeholders during Problem Scoping?","options":["To avoid collecting any data","To make the project take longer","To skip the Evaluation stage","To understand different perspectives and design a fairer solution"],"answer":3,"explain":"Identifying stakeholders helps the team see the problem from multiple viewpoints."},{"kind":"mcq","prompt":"Thinking about fairness and privacy while scoping a problem is an example of considering...","options":["Ethics","Rule-based modeling","Deployment","Data visualization"],"answer":0,"explain":"Brainstorming issues like fairness and privacy is part of thinking about ethics."}]},{"id":"pc5","title":"Data Acquisition","icon":"📥","kind":"lesson","story":"The Data Well runs deep. To draw useful water, you must know what kind of bucket to lower — and where the well actually is.","teach":[{"title":"What is Data Acquisition?","body":"This stage is about identifying what data you need and finding reliable sources to collect it, such as surveys, sensors, websites, or open databases.","visual":"🪣"},{"title":"Types of Data","body":"Data can be structured, like numbers in a spreadsheet, or unstructured, like photos, audio clips, or free-form text.","visual":"🗂️"},{"title":"Data Features","body":"Features are the specific measurable details collected about each item — for a weather project, features might be temperature, humidity, and wind speed.","visual":"🏷️"},{"title":"System Maps","body":"A system map is a diagram showing how the data features connect to each other and to the problem, helping the team see the bigger picture before building anything.","visual":"🧭"}],"questions":[{"kind":"mcq","prompt":"A spreadsheet of daily temperatures is an example of which kind of data?","options":["Structured data","Unstructured data","No data","Rule-based data"],"answer":0,"explain":"Neatly organised numbers in rows and columns are structured data."},{"kind":"mcq","prompt":"A folder of photographs used to train an image-recognition AI is an example of...","options":["A problem statement","Unstructured data","Structured data","A stakeholder"],"answer":1,"explain":"Images don't fit neatly into rows and columns, so they are unstructured data."},{"kind":"mcq","prompt":"In a project predicting exam scores, 'hours studied per week' is an example of a...","options":["Data feature","Stakeholder","4Ws canvas","Deployment plan"],"answer":0,"explain":"A data feature is a specific measurable property collected about each item, like hours studied."},{"kind":"mcq","prompt":"A diagram that shows how different data features relate to each other and the problem is called a...","options":["Bar graph","System map","Confusion table","4Ws canvas"],"answer":1,"explain":"A system map visually connects the data features involved in a problem."}]},{"id":"pc6","title":"Data Exploration & Visualization","icon":"📊","kind":"lesson","story":"Rows of raw numbers float past like fog. Only by turning them into pictures — bars, lines, and slices — can you finally see the pattern hidden inside.","teach":[{"title":"Why Visualize Data?","body":"Raw numbers are hard to read at a glance, but a graph can reveal patterns, trends, and unusual values (outliers) almost instantly.","visual":"🔎"},{"title":"Bar Graphs","body":"Bar graphs are great for comparing different categories side by side, like comparing rainfall across different cities.","visual":"📊"},{"title":"Line Graphs","body":"Line graphs show how a value changes over time, like tracking a city's temperature across the months of a year.","visual":"📈"},{"title":"Pie Charts & Scatter Plots","body":"Pie charts show how a whole is divided into parts, while scatter plots show the relationship between two different variables, like study hours and marks scored.","visual":"🥧"}],"questions":[{"kind":"mcq","prompt":"To compare the population of five different cities, which graph works best?","options":["No graph is needed","Line graph","Bar graph","Pie chart"],"answer":2,"explain":"Bar graphs are ideal for comparing separate categories like cities."},{"kind":"mcq","prompt":"To show how a student's height changed every year from age 5 to 15, the best choice is a...","options":["Line graph","Pie chart","Scatter plot","Bar graph"],"answer":0,"explain":"Line graphs are best for showing a trend over time."},{"kind":"mcq","prompt":"To show what percentage of a class prefers each of four subjects, you would use a...","options":["Line graph","Scatter plot","Pie chart","System map"],"answer":2,"explain":"Pie charts show how parts make up a whole, like percentages of a class."},{"kind":"mcq","prompt":"Which AI Project Cycle stage focuses on visualising and understanding acquired data before building a model?","options":["Problem Scoping","Modeling","Deployment","Data Exploration"],"answer":3,"explain":"Data Exploration is where collected data is analysed and visualised."}]},{"id":"pc7","title":"Modeling: Rule-Based vs Learning-Based","icon":"⚙️","kind":"lesson","story":"Two workshops stand side by side. One is stacked with hand-written rulebooks. The other hums with machines that improve every time they see something new. Which workshop builds your model?","teach":[{"title":"What is Modeling?","body":"Modeling is the stage where the AI Project Cycle turns collected data into a working model that can make decisions or predictions.","visual":"🛠️"},{"title":"Rule-Based Models","body":"A rule-based model follows fixed instructions written by humans — for example, 'if the temperature is below 0°C, say it is freezing.' It does not change unless a human updates the rules.","visual":"📜"},{"title":"Learning-Based Models","body":"A learning-based model studies examples in data and learns patterns on its own, improving its predictions as it sees more data — like an AI that gets better at recognising handwriting the more samples it sees.","visual":"🌱"},{"title":"Choosing Between Them","body":"Rule-based models are simple and predictable but can't adapt, while learning-based models can handle complex, changing situations but need lots of good data.","visual":"⚖️"}],"questions":[{"kind":"mcq","prompt":"A chatbot that always replies 'Store hours are 9 to 5' whenever it sees the word 'hours' is using a...","options":["Rule-based model","Learning-based model","Data visualization","System map"],"answer":0,"explain":"It follows a fixed, human-written instruction, which is the definition of a rule-based model."},{"kind":"mcq","prompt":"An AI that studies thousands of labeled photos of cats and dogs and gradually improves at telling them apart is a...","options":["Stakeholder","4Ws canvas","Rule-based model","Learning-based model"],"answer":3,"explain":"It learns patterns from data and improves with experience, so it is learning-based."},{"kind":"mcq","prompt":"What is a key limitation of a rule-based model?","options":["It cannot be programmed by humans","It always needs huge amounts of data","It is a type of graph","It cannot adapt to situations its rules don't cover"],"answer":3,"explain":"Rule-based models only follow the fixed rules they were given and can't handle new situations on their own."},{"kind":"mcq","prompt":"Modeling is the AI Project Cycle stage that comes right after...","options":["Data Exploration","Evaluation","Problem Scoping","Deployment"],"answer":0,"explain":"After data is explored and visualised, it is used to build the model."}]},{"id":"pc8","title":"Evaluation: TP, FP, TN, FN","icon":"🎯","kind":"lesson","story":"The Trial Chamber tests your model with real cases. Every guess your model makes will be sorted into one of four bins — and only by understanding the bins can you judge if your model is any good.","teach":[{"title":"What is Evaluation?","body":"Evaluation is the stage where we test how well a model's predictions match reality, using real examples and simple scorekeeping terms.","visual":"🧪"},{"title":"True Positive & True Negative","body":"A True Positive (TP) is when the model correctly says 'yes' — and it really is a yes. A True Negative (TN) is when it correctly says 'no' — and it really is a no.","visual":"✅"},{"title":"False Positive & False Negative","body":"A False Positive (FP) is a false alarm — the model says 'yes' but it's actually a 'no'. A False Negative (FN) is a miss — the model says 'no' but it's actually a 'yes'.","visual":"❌"},{"title":"Example: Spam Filter","body":"If 'spam' is the positive label: correctly flagging a spam email is a TP, wrongly flagging a normal email as spam is a FP, correctly letting a normal email through is a TN, and letting real spam through by mistake is a FN.","visual":"📧"}],"questions":[{"kind":"mcq","prompt":"A medical AI test says a healthy person has a disease. This is an example of a...","options":["True Positive","False Negative","False Positive","True Negative"],"answer":2,"explain":"The model raised a false alarm — predicted 'yes' (has disease) when the truth is 'no'."},{"kind":"mcq","prompt":"A smoke detector correctly stays silent when there is no fire. This is an example of a...","options":["False Positive","True Positive","True Negative","False Negative"],"answer":2,"explain":"The model correctly predicted 'no fire', and there really was no fire."},{"kind":"mcq","prompt":"A spam filter fails to catch a real spam email, letting it land in the inbox. This is an example of a...","options":["True Positive","False Positive","False Negative","True Negative"],"answer":2,"explain":"The model predicted 'not spam' (no) when the email actually was spam (yes) — a missed case."},{"kind":"numeric","prompt":"A fruit-sorting AI checks 5 apples for bruises (positive = 'bruised'). It predicted: Apple 1 = bruised, Apple 2 = bruised, Apple 3 = bruised, Apple 4 = not bruised, Apple 5 = not bruised. In reality: Apple 1 and Apple 2 are truly bruised, Apple 3 is actually fine, Apple 4 is actually bruised (missed by the AI), and Apple 5 is truly fine. How many True Positives did the AI get?","answer":2,"explain":"Apples 1 and 2 were correctly predicted as bruised and truly were bruised — that's 2 True Positives."},{"kind":"numeric","prompt":"Same apple scenario: 5 apples checked for bruises (positive = 'bruised'). Predicted: Apple 1 = bruised, Apple 2 = bruised, Apple 3 = bruised, Apple 4 = not bruised, Apple 5 = not bruised. Actual: Apple 1 and Apple 2 truly bruised, Apple 3 actually fine, Apple 4 actually bruised (missed), Apple 5 truly fine. How many False Positives did the AI get?","answer":1,"explain":"Apple 3 was predicted bruised but was actually fine — that's 1 False Positive."}]},{"id":"pc9","title":"Deployment, Ethics, Bias & Access","icon":"🌐","kind":"lesson","story":"The final gate of the observatory opens onto the real world. Your model must now serve real people — fairly, safely, and honestly. The Study Atlas watches to see if you're ready.","teach":[{"title":"Deployment","body":"Deployment is when the finished AI solution is released for people to actually use — but the work doesn't stop there, since it needs to be monitored and improved over time.","visual":"🚀"},{"title":"AI Ethics","body":"AI ethics means thinking about fairness, privacy, honesty, and responsibility at every stage of a project — asking not just 'can we build this?' but 'should we, and how do we do it right?'","visual":"⚖️"},{"title":"Seeing Multiple Perspectives","body":"Role-playing as different stakeholders — like a patient, a doctor, and a hospital — helps reveal ethical concerns that a single point of view might miss.","visual":"🎭"},{"title":"AI Bias","body":"Bias happens when the data used to train an AI doesn't fairly represent everyone, causing the model to make unfair or inaccurate predictions for some groups.","visual":"⚠️"},{"title":"AI Access","body":"Not everyone has equal access to AI's benefits — cost, language, internet availability, and device access can all leave some communities behind, so it's worth weighing AI's benefits against its harms.","visual":"🌍"}],"questions":[{"kind":"mcq","prompt":"If a face-recognition AI is trained mostly on photos of one skin tone, it may perform poorly on others. This is an example of...","options":["Deployment","A 4Ws canvas","Rule-based modeling","AI bias"],"answer":3,"explain":"The training data isn't representative of everyone, leading to unfair results — that's bias."},{"kind":"mcq","prompt":"A community without reliable internet cannot benefit from a new AI health app. This mainly highlights an issue of...","options":["Evaluation","AI access","Modeling","Data visualization"],"answer":1,"explain":"Unequal access to the internet or devices is an AI access issue."},{"kind":"mcq","prompt":"Considering fairness, privacy, and responsibility throughout an AI project is called...","options":["AI ethics","True Positive rate","System mapping","Data acquisition"],"answer":0,"explain":"AI ethics is about thinking through fairness, privacy, and responsibility."},{"kind":"mcq","prompt":"Once an AI solution is released for people to actually use, the project has reached the stage of...","options":["Problem Scoping","Data Exploration","Deployment","Modeling"],"answer":2,"explain":"Deployment is when the finished solution goes into real-world use."}]},{"id":"pc-boss","title":"The Glitch Overlord","icon":"👾","kind":"boss","boss":{"name":"The Glitch Overlord","taunt":"Six stages, three domains, four Ws — mess up one and your whole project crashes... just like me!"},"story":"The Glitch Overlord has scrambled the observatory's archives. Answer its trials correctly to restore order to the AI Project Cycle and save the Study Atlas.","teach":[],"questions":[{"kind":"mcq","prompt":"Which AI domain helps a machine understand spoken or written language?","options":["Deployment","Data & Statistics","Computer Vision","Natural Language Processing"],"answer":3,"explain":"NLP focuses on understanding and generating human language."},{"kind":"numeric","prompt":"How many stages are there in the AI Project Cycle?","answer":6,"explain":"Problem Scoping, Data Acquisition, Data Exploration, Modeling, Evaluation, Deployment."},{"kind":"mcq","prompt":"In the 4Ws canvas, 'Why should this problem be solved?' is answered under...","options":["What","Why","Where","Who"],"answer":1,"explain":"'Why' captures the benefit and importance of solving the problem."},{"kind":"mcq","prompt":"A model that follows fixed if-then instructions written by a human, without learning from new data, is...","options":["A system map","Rule-based","A stakeholder","Learning-based"],"answer":1,"explain":"Rule-based models strictly follow human-written rules and don't adapt on their own."},{"kind":"mcq","prompt":"A security camera AI correctly identifies an intruder as an intruder. This is a...","options":["True Negative","False Negative","True Positive","False Positive"],"answer":2,"explain":"The model correctly predicted 'yes' (intruder), and it really was an intruder."},{"kind":"mcq","prompt":"A doctor-assist AI wrongly tells a sick patient they are healthy. This is a...","options":["False Negative","True Positive","False Positive","True Negative"],"answer":0,"explain":"The model predicted 'no' (healthy) but the truth was 'yes' (sick) — a dangerous miss."},{"kind":"mcq","prompt":"An AI hiring tool trained mostly on past resumes from one group of people may unfairly favor that group. This shows the danger of...","options":["AI bias","Data visualization","The 4Ws canvas","Rule-based modeling"],"answer":0,"explain":"Unrepresentative training data can lead to biased, unfair predictions."},{"kind":"mcq","prompt":"Listing everyone affected by a problem — like users, workers, and the community — happens when identifying the...","options":["Data features","Stakeholders","Evaluation score","Graph type"],"answer":1,"explain":"Stakeholders are all the people connected to or affected by the problem."}]}]},{"id":"dataliteracy9","index":1,"name":"Data Literacy","subtitle":"Artificial Intelligence — Unit 2","emoji":"📊","palette":{"from":"#fb7185","to":"#881337"},"lessons":[{"id":"dl1","title":"The Language of Data","icon":"🧭","kind":"lesson","story":"You've just been sworn into the Study Atlas Data Guild as a trainee analyst. Your first mission: learn to read the strange new language that powers every AI system in the Atlas — data — before a rival guild misreads a chart and starts a citywide panic.","teach":[{"title":"What is Data Literacy?","body":"Data literacy is the ability to find, read, question, and understand data, and then use it to make decisions or explain conclusions to others. It is not about memorising numbers — it is about knowing what data means and where it came from.","visual":"🧠"},{"title":"Why Data Literacy Matters","body":"A data-literate person can tell a trustworthy, well-supported claim apart from a misleading one, such as a headline that hides important numbers. This helps you make informed, confident decisions instead of being fooled by cherry-picked statistics.","visual":"🔍"},{"title":"Becoming Data Literate","body":"You build data literacy by practising regularly: asking where a dataset came from, checking it for bias or gaps, reading charts carefully instead of skimming headlines, and questioning claims before accepting them.","visual":"🏋️"}],"questions":[{"kind":"mcq","prompt":"Which statement best describes data literacy?","options":["The ability to memorise as many numbers as possible","The ability to find, understand, question, and communicate data","The ability to draw pictures by hand","The ability to write computer programs"],"answer":1,"explain":"Data literacy is about reading, questioning, and communicating data effectively, not memorising figures."},{"kind":"mcq","prompt":"Why does data literacy help with informed decision-making?","options":["It guarantees every dataset you see is completely accurate","It replaces the need for critical thinking","It helps you judge whether a data-based claim is trustworthy before acting on it","It lets you skip checking where data came from"],"answer":2,"explain":"Being data literate means you can evaluate claims critically instead of accepting them blindly."},{"kind":"mcq","prompt":"A news article claims 'Sales tripled this month!' but never shows the actual starting and ending numbers. What should a data-literate reader do?","options":["Assume it must be true since it was published","Ignore the claim completely without checking anything","Share the article immediately because it sounds impressive","Ask for the actual figures before believing the claim"],"answer":3,"explain":"A data-literate reader looks for the real numbers behind a claim instead of trusting a dramatic headline."},{"kind":"mcq","prompt":"Which activity best helps a person become more data literate over time?","options":["Trusting every statistic shared on social media","Regularly questioning the source and meaning of data you encounter","Only reading data once a year","Avoiding all charts and graphs"],"answer":1,"explain":"Data literacy grows through practice — regularly questioning sources, checking for bias, and reading data carefully."}]},{"id":"dl2","title":"The Five-Step Framework","icon":"🗺️","kind":"lesson","story":"An ancient sensor in the Atlas archives has recorded a mysterious stream of numbers. The Guild's master analyst hands you a five-step map — the Data Literacy Process Framework — and tells you it is the only way to safely turn raw signals into real answers.","teach":[{"title":"Step 1: Ask a Question","body":"Every data investigation starts with a clear question you want answered. A focused question tells you exactly what data you need to collect and how to analyse it later.","visual":"❓"},{"title":"Step 2 & 3: Acquire, then Process","body":"Next, you acquire (collect) data that can answer your question. Then you process it — cleaning it up and organising it — so you can look for patterns, trends, or relationships.","visual":"⚙️"},{"title":"Step 4: Interpret","body":"Interpreting means figuring out what the patterns actually mean in the real world, while checking the data for bias or limitations so your conclusions stay fair and accurate.","visual":"💡"},{"title":"Step 5: Communicate and Apply","body":"Finally, you share your findings clearly, using words and visuals like charts, and use them to make a decision or take real action.","visual":"📢"}],"questions":[{"kind":"mcq","prompt":"Which step of the data literacy process framework should come first?","options":["Asking a clear question about what you want to find out","Interpreting the results","Communicating your final findings","Making a decision"],"answer":0,"explain":"The framework begins with a clear question, which guides every step that follows."},{"kind":"mcq","prompt":"In the data literacy process, what comes right after acquiring (collecting) data?","options":["Deleting the data","Asking the original question again","Publishing the data without checking it","Processing the data to organise it and look for patterns"],"answer":3,"explain":"After data is collected, it must be processed (cleaned and organised) before it can be analysed further."},{"kind":"mcq","prompt":"Why is the 'interpret' step important, and not just 'process'?","options":["Interpreting means deleting data you don't like","Interpreting explains what the patterns actually mean, beyond just organising numbers","Interpreting is only needed for pictures, not numbers","Interpreting replaces the need to ask a question"],"answer":1,"explain":"Processing organises the data, but interpreting is where you explain its real-world meaning."},{"kind":"mcq","prompt":"After interpreting data and drawing a conclusion, what is the final step in the framework?","options":["Going back and collecting completely different data","Stopping without sharing anything","Hiding the results from others","Communicating the findings clearly and applying them"],"answer":3,"explain":"The framework ends with clearly communicating findings and applying them to real decisions."}]},{"id":"dl3","title":"Privacy or Security?","icon":"🔐","kind":"lesson","story":"At the gates of the Data Vault stand two guardians who look identical but guard very different things. To pass, you must prove you know exactly what separates data privacy from data security — and why AI systems care about both.","teach":[{"title":"Data Privacy","body":"Data privacy is about who is allowed to collect, see, and use someone's personal data, and making sure people give proper consent and have control over their own information.","visual":"🙈"},{"title":"Data Security","body":"Data security is about protecting data from theft, damage, or unauthorised access, using tools like strong passwords, encryption, and firewalls to keep it safe.","visual":"🛡️"},{"title":"How They Relate to AI","body":"AI systems are trained on huge amounts of data, which is often personal. Without strong privacy rules and security protections, this data can be misused, stolen, or exposed, harming the very people it came from.","visual":"🤖"}],"questions":[{"kind":"mcq","prompt":"What is the main difference between data privacy and data security?","options":["Privacy and security mean exactly the same thing","Security is about consent; privacy is about passwords","Privacy is about who may access or use data; security is about protecting data from theft or damage","Privacy only applies to computers, not people"],"answer":2,"explain":"Privacy governs who can access and use data appropriately, while security focuses on protecting data from unauthorized access."},{"kind":"mcq","prompt":"An app asks for your permission before using your location. This is mainly an example of ___.","options":["data preprocessing","data security","data privacy","data visualization"],"answer":2,"explain":"Asking for permission and giving users control over their data is about privacy."},{"kind":"mcq","prompt":"A hospital encrypts its patient records so hackers cannot read them even if the files are stolen. This is mainly an example of ___.","options":["data acquisition","data privacy","data security","data interpretation"],"answer":2,"explain":"Encryption is a technical measure that protects data from being accessed or misused — that is data security."},{"kind":"mcq","prompt":"Why do data privacy and security matter especially for AI systems?","options":["AI systems never use any personal data at all","Privacy only matters for AI, not for regular apps","AI systems cannot be hacked, so security is unnecessary","AI is trained on large amounts of data, often personal, which can be misused if not protected"],"answer":3,"explain":"Because AI relies heavily on data, much of it personal, poor privacy and security can lead to real harm."}]},{"id":"dl4","title":"Breach Alert!","icon":"🚨","kind":"lesson","story":"Sirens wail across the Data Vault — an alarm signals a possible breach! Before the Guild's systems are compromised, you must understand what a data breach really is and patch the weak points with solid cyber-safety habits.","teach":[{"title":"What is a Data Breach?","body":"A data breach happens when data is accessed, stolen, or leaked without permission. This can expose passwords, personal details, or financial information to people who should never see them.","visual":"🕳️"},{"title":"Risks of a Breach","body":"A breach can lead to identity theft, financial loss, blackmail, or serious damage to a person's or organisation's reputation, sometimes affecting thousands of people at once.","visual":"⚠️"},{"title":"Cyber-Safety Best Practices","body":"Protect yourself by using strong, unique passwords, enabling two-factor authentication, avoiding suspicious links or attachments, keeping software updated, and not oversharing personal information online.","visual":"✅"}],"questions":[{"kind":"mcq","prompt":"What is a data breach?","options":["A password that is very easy to remember","A new feature added to an app","A backup copy of your data stored safely","An incident where data is accessed or leaked without authorization"],"answer":3,"explain":"A data breach is unauthorized access to or exposure of data."},{"kind":"mcq","prompt":"Which of these is a strong cyber-safety practice?","options":["Clicking on every link sent to you, even from unknown senders","Using a strong, unique password and enabling two-factor authentication","Sharing your passwords with friends so they can log in for you","Using the same simple password for every account"],"answer":1,"explain":"Unique strong passwords plus two-factor authentication make accounts much harder to break into."},{"kind":"mcq","prompt":"Which of these is a real risk of a data breach?","options":["Identity theft using someone's stolen personal information","Faster internet speeds for everyone","Free upgrades to all affected accounts","Automatic improvement of data quality"],"answer":0,"explain":"Stolen personal data is often used to commit identity theft or fraud."},{"kind":"mcq","prompt":"You get an email from an unknown sender saying 'Claim your prize now — click here!'. What is the safest action?","options":["Click the link immediately to see the prize","Reply with your bank account details to be safe","Forward it to all your friends right away","Don't click it; delete it or report it as suspicious"],"answer":3,"explain":"Unexpected 'prize' links from unknown senders are a classic cyber-safety red flag and should never be clicked."}]},{"id":"dl5","title":"Sorting the Data Crystals","icon":"🔷","kind":"lesson","story":"Deep in the Data Vault you discover a chest of glowing crystals, each holding a different kind of data. To unlock the next chamber, you must sort every crystal into its correct category.","teach":[{"title":"Quantitative vs Qualitative","body":"Quantitative data is numeric, like heights, exam scores, or temperatures. Qualitative data is descriptive, like favourite colours, opinions, or categories, and is usually expressed in words.","visual":"🔢"},{"title":"Structured vs Unstructured","body":"Structured data fits neatly into rows and columns, like a spreadsheet of names and marks. Unstructured data has no fixed format, such as photos, videos, or free-form text.","visual":"🗂️"},{"title":"Primary vs Secondary","body":"Primary data is collected firsthand by you, for your own purpose, such as a survey you run yourself. Secondary data was collected earlier by someone else for a different purpose, such as a government census report you reuse.","visual":"🧾"}],"questions":[{"kind":"mcq","prompt":"A student's exam score of 87 is an example of ___ data.","options":["qualitative","secondary","quantitative","unstructured"],"answer":2,"explain":"A numeric measurement like a score is quantitative data."},{"kind":"mcq","prompt":"A list of students' favourite colours, written as words, is an example of ___ data.","options":["structured only","qualitative","primary always","quantitative"],"answer":1,"explain":"Descriptive, non-numeric information like favourite colours is qualitative data."},{"kind":"mcq","prompt":"A spreadsheet with names, ages, and marks arranged neatly in rows and columns is ___ data.","options":["secondary","unstructured","qualitative","structured"],"answer":3,"explain":"Data organised into a fixed row-and-column format is structured data."},{"kind":"mcq","prompt":"Photos and voice recordings, which don't fit neatly into a table, are examples of ___ data.","options":["quantitative","unstructured","primary","structured"],"answer":1,"explain":"Data without a fixed, predictable format, like images or audio, is unstructured data."},{"kind":"mcq","prompt":"If you personally design and run a survey in your class, the data you collect is called ___ data.","options":["unstructured","secondary","qualitative","primary"],"answer":3,"explain":"Data collected firsthand for your own purpose is primary data."}]},{"id":"dl6","title":"Gathering the Evidence","icon":"🎒","kind":"lesson","story":"The Guild sends you out into the field on your first real mission: gather solid evidence about the Atlas's weather patterns. But not all data-gathering methods are equally trustworthy — choose carefully.","teach":[{"title":"What is Data Acquisition?","body":"Data acquisition is the process of collecting data from various sources so it can later be processed and analysed.","visual":"📥"},{"title":"Common Acquisition Methods","body":"Data can be acquired through surveys and questionnaires, interviews, direct observation, sensors and IoT devices, or by using existing databases and open datasets.","visual":"🧰"},{"title":"Best Practices for Acquiring Data","body":"Always use reliable and relevant sources, get proper consent when collecting personal data, make sure your sample is representative and not biased, and record where the data came from.","visual":"✔️"}],"questions":[{"kind":"mcq","prompt":"Which of these is a method of data acquisition?","options":["Deleting old files","Conducting a survey","Drawing a pie chart","Encrypting a password"],"answer":1,"explain":"A survey is a common way to collect (acquire) new data directly from people."},{"kind":"mcq","prompt":"Why is it a best practice to check whether a data source is reliable before using it?","options":["Unreliable sources can lead to incorrect conclusions","Reliable sources are always free of charge","It makes the dataset look bigger","It is not actually important"],"answer":0,"explain":"Using an unreliable source can produce misleading results, so checking reliability is essential."},{"kind":"mcq","prompt":"Automatically recording temperature every hour using a weather sensor is an example of data acquired through ___.","options":["interviews","questionnaires","secondary reports only","sensors/IoT devices"],"answer":3,"explain":"Sensors and IoT devices can automatically collect data like temperature readings over time."},{"kind":"mcq","prompt":"Why is getting consent important when acquiring personal data from people?","options":["It respects people's privacy and is often legally required","Consent is never actually necessary","It is only needed for numeric data, not opinions","It makes the data collection process slower for no reason"],"answer":0,"explain":"Consent protects people's privacy rights and is a key best practice — and often a legal requirement — in data acquisition."}]},{"id":"dl7","title":"Cleaning the Raw Ore","icon":"🧹","kind":"lesson","story":"The evidence you gathered arrives as raw, messy 'data ore' — full of gaps, duplicates, and errors. Before the Guild's analysts can use it, you must refine it into something clean and usable.","teach":[{"title":"Features of Data","body":"A feature is an individual measurable property or characteristic in a dataset — for example, in a table of students, 'Age' and 'Marks' are each features (columns).","visual":"🏷️"},{"title":"Why Preprocess Data?","body":"Raw data collected in the real world is often messy — it can have missing values, duplicate entries, or errors, which can mislead analysis if they are not fixed first.","visual":"🧽"},{"title":"Common Preprocessing Steps","body":"Data preprocessing includes cleaning (fixing or removing errors and duplicates), handling missing values, and organising or formatting data consistently before it is analysed.","visual":"🔧"}],"questions":[{"kind":"mcq","prompt":"In a dataset of students with columns 'Name', 'Age', and 'Marks', each column represents a ___.","options":["dashboard","breach","feature","framework"],"answer":2,"explain":"A feature is a measurable property or column in a dataset."},{"kind":"mcq","prompt":"Why is data preprocessing necessary before analysis?","options":["Preprocessing makes data impossible to analyse","It is only needed for pictures, never for numbers","Raw data is always perfectly clean already","Raw data is often messy, with errors or missing values that could mislead results"],"answer":3,"explain":"Preprocessing fixes messiness in raw data so analysis produces accurate, trustworthy results."},{"kind":"mcq","prompt":"Removing duplicate entries from a dataset before analysing it is part of which process?","options":["cyber-safety","data acquisition","data visualization","data preprocessing"],"answer":3,"explain":"Cleaning up duplicates is a key part of data preprocessing."},{"kind":"mcq","prompt":"A dataset has several students with a blank 'Age' field. Which preprocessing step directly addresses this problem?","options":["getting consent","handling missing values","encryption","data visualization"],"answer":1,"explain":"Blank or missing entries are fixed during the 'handling missing values' step of preprocessing."}]},{"id":"dl8","title":"Reading the Signs","icon":"🔎","kind":"lesson","story":"The cleaned data now sits before you, but it still looks like a puzzle of numbers and words. The Guild elder warns: a town nearby depends on you correctly interpreting these signs before deciding what to do next.","teach":[{"title":"What is Data Interpretation?","body":"Data interpretation is the process of making sense of processed data — identifying patterns, trends, and relationships, and explaining what they actually mean.","visual":"🧩"},{"title":"Types of Data Interpretation","body":"Qualitative interpretation explains data in descriptive, non-numeric terms, such as common themes in comments. Quantitative interpretation uses numbers and statistics, such as averages or percentages, to draw conclusions.","visual":"⚖️"},{"title":"Importance of Data Interpretation","body":"Data interpretation turns raw numbers into useful insights, supports informed decision-making, and helps people spot trends or problems before they grow bigger.","visual":"🎯"}],"questions":[{"kind":"mcq","prompt":"What is data interpretation?","options":["Encrypting data so no one can read it","Deleting data that looks confusing","Making sense of data by identifying patterns and explaining what they mean","Collecting brand new data from scratch"],"answer":2,"explain":"Interpretation is about explaining what patterns in the data actually mean."},{"kind":"mcq","prompt":"Explaining survey results by describing common themes in people's written answers (not using numbers) is an example of ___ interpretation.","options":["structured","unstructured only","quantitative","qualitative"],"answer":3,"explain":"Describing themes in words, rather than numbers, is qualitative interpretation."},{"kind":"mcq","prompt":"Using statistics like averages and percentages to draw conclusions from a dataset is an example of ___ interpretation.","options":["qualitative","quantitative","secondary","primary"],"answer":1,"explain":"Using numeric statistics to draw conclusions is quantitative interpretation."},{"kind":"mcq","prompt":"Why is data interpretation important?","options":["It guarantees a dataset has no errors","It is only useful for making charts look colourful","It turns raw data into insights that support informed decisions","It removes the need to ever collect more data"],"answer":2,"explain":"Interpretation is what makes data genuinely useful for decision-making, not just decorative."},{"kind":"numeric","prompt":"A shop recorded its sales for five days: Mon 10, Tue 15, Wed 12, Thu 20, Fri 18. What is the highest sales value recorded in this data?","answer":20,"explain":"Comparing all five values, Thursday's 20 is the highest — reading off the maximum value is a basic step in interpreting data."}]},{"id":"dl-boss","title":"The Dashboard Showdown","icon":"📊","kind":"boss","story":"At the heart of the Data Vault, a shape-shifting cryptid made of tangled numbers and mismatched charts blocks your path. To defeat the Chart Cryptid, you must prove you have mastered everything about data literacy — from privacy to visualization.","boss":{"name":"The Chart Cryptid","taunt":"Numbers are boring on their own... let's see if YOU can turn my chaos into a clear chart, trainee!"},"teach":[{"title":"Why Visualize Data?","body":"Data visualization turns raw numbers into charts and graphs, which are faster and easier for people to understand, compare, and spot trends in than tables full of raw numbers.","visual":"📈"},{"title":"Common Types of Visualizations","body":"Bar charts compare values across categories, line charts show trends over time, and pie charts show how parts make up a whole. Choosing the right chart type makes your message clearer.","visual":"📉"},{"title":"What is a Dashboard?","body":"A dashboard is an interactive display that combines multiple visualizations and key figures in one place — tools like Tableau are used to build dashboards so people can monitor and explore data in real time.","visual":"🖥️"}],"questions":[{"kind":"mcq","prompt":"What is the main benefit of data visualization?","options":["It hides data so nobody can see it","It automatically fixes errors in a dataset","It makes patterns and trends in data easier to see and understand quickly","It replaces the need to collect any data"],"answer":2,"explain":"Visualization turns raw data into a form that is faster and easier for people to understand."},{"kind":"mcq","prompt":"Which chart type is best for showing how something changes over time, like daily temperature across a week?","options":["pie chart","line chart","a random scatter of unrelated dots","a single unlabeled number"],"answer":1,"explain":"Line charts are well suited to showing trends over time."},{"kind":"mcq","prompt":"Which chart type is best for showing proportions of a whole, like the percentage share of each fruit in a fruit basket?","options":["an encrypted file","a plain list of numbers","line chart","pie chart"],"answer":3,"explain":"Pie charts are designed to show how parts make up a whole."},{"kind":"mcq","prompt":"An interactive screen combining multiple charts and key figures in one place, used to monitor data at a glance, is called a ___.","options":["dashboard","breach","questionnaire","feature"],"answer":0,"explain":"A dashboard brings together multiple visualizations so data can be monitored in one view."},{"kind":"mcq","prompt":"Which term describes protecting data from hackers using tools like encryption and strong passwords?","options":["data privacy","data interpretation","data security","data visualization"],"answer":2,"explain":"Protecting data from theft or unauthorized access is data security."},{"kind":"mcq","prompt":"A collection of open-ended written comments from a customer survey (not numbers) is an example of ___ data.","options":["structured only","quantitative","qualitative","encrypted"],"answer":2,"explain":"Descriptive, word-based data like comments is qualitative data."},{"kind":"mcq","prompt":"Fixing missing values and removing duplicates in a dataset before analyzing it is called ___.","options":["data privacy","data preprocessing","data breach","dashboarding"],"answer":1,"explain":"Cleaning and organising raw data before analysis is data preprocessing."},{"kind":"mcq","prompt":"Which step of the Data Literacy Process Framework comes first, before acquiring or analysing any data?","options":["asking a clear question about what you want to find out","encrypting the raw data","deleting duplicate entries","publishing the final dashboard"],"answer":0,"explain":"The framework begins by asking a clear question, which then guides data acquisition and analysis."}]}]},{"id":"mathforai9","index":2,"name":"Math for AI (Statistics & Probability)","subtitle":"Artificial Intelligence — Unit 3","emoji":"📐","palette":{"from":"#4ade80","to":"#14532d"},"lessons":[{"id":"ma1","title":"Why Math Matters for AI","icon":"🧮","kind":"lesson","story":"You step into the Number Nebula, a swirling galaxy where every star is secretly a digit. The Atlas Guide whispers: \"AI can't think without math — it finds patterns in numbers and pictures the way you'd spot a friend in a crowd.\" Ready to see how?","teach":[{"title":"AI hunts for patterns","body":"AI systems look at huge piles of numbers and images and try to find patterns or relationships hidden inside them. Once a pattern is found, the AI can use it to make predictions about new data it has never seen before.","visual":"🔍"},{"title":"The four math pillars of AI","body":"AI leans on four big branches of math: Statistics (making sense of data), Linear Algebra (working with grids of numbers), Probability (measuring how likely something is), and Calculus (measuring how things change). This unit focuses on Statistics and Probability.","visual":"🏛️"},{"title":"Numbers and images, same idea","body":"Whether the data is a list of exam scores or a photo made of tiny colored dots called pixels, AI treats both as numbers and searches for patterns — that is the core skill behind almost every AI system.","visual":"🖼️"}],"questions":[{"kind":"mcq","prompt":"What is the main thing AI tries to do when it looks at numbers or images?","options":["Find patterns and relationships hidden in the data","Print the data on paper","Delete the data to save space","Ignore the data completely"],"answer":0,"explain":"AI's core job is to spot patterns in data so it can make predictions or decisions."},{"kind":"mcq","prompt":"Which branch of math is mainly used to measure how likely something is to happen?","options":["Geometry","Calculus","Linear Algebra","Probability"],"answer":3,"explain":"Probability tells us how likely an event is, which is essential for AI predictions."},{"kind":"mcq","prompt":"Which of these is NOT one of the four math pillars AI relies on?","options":["Probability","Statistics","Grammar","Calculus"],"answer":2,"explain":"Grammar is a language topic, not one of the four math pillars — Statistics, Linear Algebra, Probability and Calculus are."},{"kind":"mcq","prompt":"A tiny colored dot that makes up a digital image is called a ___.","options":["node","pixel","vector","byte"],"answer":1,"explain":"Images are made of pixels, and AI treats each pixel's value as a number to analyse."}]},{"id":"ma2","title":"Cracking Number Patterns","icon":"🔢","kind":"lesson","story":"A locked gate in the Nebula only opens for those who can finish its number riddles. Carved into the stone are sequences with one digit missing — the gate hums, waiting for you to spot the pattern.","teach":[{"title":"Arithmetic patterns","body":"In an arithmetic pattern, you add (or subtract) the same number each time to get the next term. For example, in 7, 11, 15, 19, the pattern adds 4 each step.","visual":"➕"},{"title":"Geometric patterns","body":"In a geometric pattern, you multiply (or divide) by the same number each time. For example, 2, 4, 8, 16 doubles at every step.","visual":"✖️"},{"title":"Special patterns","body":"Some patterns follow a special rule, like squares (1, 4, 9, 16 — each is a number multiplied by itself) or the Fibonacci pattern (1, 1, 2, 3, 5 — each term is the sum of the two before it). AI models learn to spot rules like these in real data too.","visual":"⭐"}],"questions":[{"kind":"numeric","prompt":"Find the missing number: 7, 11, 15, 19, ___","answer":23,"explain":"The pattern adds 4 each time: 19 + 4 = 23."},{"kind":"numeric","prompt":"Find the missing number: 2, 4, 8, 16, ___","answer":32,"explain":"The pattern doubles each time: 16 x 2 = 32."},{"kind":"numeric","prompt":"Find the missing number (square numbers): 1, 4, 9, 16, 25, ___","answer":36,"explain":"These are square numbers (1x1, 2x2, 3x3...); 6x6 = 36."},{"kind":"numeric","prompt":"Find the missing number (Fibonacci pattern): 1, 1, 2, 3, 5, ___","answer":8,"explain":"Each number is the sum of the two before it: 3 + 5 = 8."},{"kind":"mcq","prompt":"What rule turns 5 into 10, 10 into 20, and 20 into 40?","options":["Multiply by 2 each time","Subtract 5 each time","Divide by 2 each time","Add 2 each time"],"answer":0,"explain":"Each term is double the one before it, so the rule is 'multiply by 2'."}]},{"id":"ma3","title":"Picture Analogy Puzzles","icon":"🧩","kind":"lesson","story":"Beyond the gate lies the Mirror Hall, where paintings hang in matching pairs. The Atlas Guide explains that AI uses this exact trick — comparing images to find connections — to recognise faces and objects.","teach":[{"title":"What is a picture analogy?","body":"A picture analogy asks: 'Image A is to Image B, as Image C is to ___?' You must find the relationship between the first pair and apply the same relationship to the second pair.","visual":"🖼️"},{"title":"Why AI cares about analogies","body":"Finding connections between sets of images helps AI solve problems like recognising that a 'kitten' relates to a 'cat' the same way a 'puppy' relates to a 'dog' — this is how image-recognition systems learn categories.","visual":"🐱"}],"questions":[{"kind":"mcq","prompt":"Sun is to Day as Moon is to ___","options":["Night","Rain","Cloud","Star"],"answer":0,"explain":"The Sun is linked to Day the same way the Moon is linked to Night."},{"kind":"mcq","prompt":"Puppy is to Dog as Kitten is to ___","options":["Fish","Bird","Cow","Cat"],"answer":3,"explain":"A puppy is a baby dog, and a kitten is a baby cat — the same 'baby of' relationship."},{"kind":"mcq","prompt":"Wheel is to Car as Wing is to ___","options":["Book","Airplane","Shoe","Table"],"answer":1,"explain":"A wheel helps a car move, just as a wing helps an airplane fly — matching parts to their vehicles."},{"kind":"mcq","prompt":"Why does AI use picture analogy puzzles?","options":["To delete unwanted photos","To change picture colors randomly","To make images bigger","To find visual relationships between images and use them to solve new problems"],"answer":3,"explain":"Picture analogies train AI to spot relationships between images, which helps it solve related problems later."}]},{"id":"ma4","title":"Statistics in the Real World","icon":"📊","kind":"lesson","story":"You arrive at the Data Observatory, where giant screens flash numbers from floods, football matches, hospitals, and storms. The Atlas Guide says one science ties them all together: statistics.","teach":[{"title":"What is statistics?","body":"Statistics is the science of collecting, organising, analysing, and interpreting data so we can understand it and make good decisions from it.","visual":"📈"},{"title":"Statistics saves lives and predicts trouble","body":"In disaster management, scientists study years of rainfall and river-level data to predict floods before they happen. In disease prediction, doctors track how many people fall sick each day to predict and slow down outbreaks.","visual":"🌊"},{"title":"Statistics in sports and weather","body":"In sports, coaches study a player's past scores to plan strategy. In weather forecasting, meteorologists analyse years of temperature and rainfall data to predict tomorrow's weather.","visual":"🏏"}],"questions":[{"kind":"mcq","prompt":"Statistics is best defined as ___","options":["the science of collecting, organising, analysing and interpreting data","a way to draw pictures","a type of computer virus","a method of deleting old files"],"answer":0,"explain":"Statistics is all about working with data from collection to interpretation."},{"kind":"mcq","prompt":"Scientists studying 50 years of river-level data to predict floods are using statistics for ___","options":["Painting","Cooking","Disaster management","Music composition"],"answer":2,"explain":"Analysing past disaster data to predict future events is a key use of statistics in disaster management."},{"kind":"mcq","prompt":"A cricket coach studies a batsman's scores from the last 20 matches to plan strategy. This is statistics applied to ___","options":["Weather forecasting","Sports","Traffic estimation","Disease prediction"],"answer":1,"explain":"Analysing a player's past performance data is a sports application of statistics."},{"kind":"numeric","prompt":"A hospital records 40 flu cases in week 1 and 65 flu cases in week 2. By how many cases did the flu count increase?","answer":25,"explain":"65 - 40 = 25 more cases, which is exactly the kind of trend statistics helps track for disease prediction."},{"kind":"mcq","prompt":"Meteorologists study years of past temperature and rainfall data to predict tomorrow's weather. This is an example of statistics used in ___","options":["Weather forecast","Sports","Traffic estimation","Disaster management"],"answer":0,"explain":"Analysing historical weather patterns to make predictions is the weather-forecast application of statistics."}]},{"id":"ma5","title":"Car Spotting: Data Collection & Tabulation","icon":"🚗","kind":"lesson","story":"The Atlas Guide hands you a clipboard and points to a busy road: \"Every AI starts life as raw, messy data. Today, you're the data collector — tally the cars as they pass and turn chaos into a neat table.\"","teach":[{"title":"Data collection","body":"Data collection means gathering facts and observations — like the colour of every car that passes by — before any analysis can happen. Good data collection is the foundation AI is built on.","visual":"📝"},{"title":"Tabulation with tally marks","body":"Tabulation means organising collected data into a table, often using tally marks to count how many times each item appears, making the data easy to read and analyse.","visual":"🗂️"}],"questions":[{"kind":"numeric","prompt":"While car spotting, you tally: Red = 6, Blue = 9, White = 14, Black = 5, Silver = 2. How many cars did you spot in total?","answer":36,"explain":"6 + 9 + 14 + 5 + 2 = 36 cars in total."},{"kind":"mcq","prompt":"Using the same tally (Red 6, Blue 9, White 14, Black 5, Silver 2), which colour was spotted most often?","options":["White","Blue","Red","Silver"],"answer":0,"explain":"White has the highest tally at 14, so it is the most frequently spotted colour."},{"kind":"numeric","prompt":"Using the same tally, how many more White cars were spotted than Red cars?","answer":8,"explain":"14 White cars minus 6 Red cars = 8 more White cars."},{"kind":"mcq","prompt":"Why is data collection important for Artificial Intelligence?","options":["It is only useful for artists","It makes computers run slower","It has nothing to do with AI","It provides the raw information AI systems need to find patterns and make decisions"],"answer":3,"explain":"Data collection forms the basis of statistics and the interpretation that AI depends on."}]},{"id":"ma6","title":"Mean, Median & Mode","icon":"⚖️","kind":"lesson","story":"In the Hall of Averages, three golden scales stand side by side, each demanding a different kind of balance. The Atlas Guide grins: \"Master Mean, Median and Mode, and you'll be able to summarise any pile of numbers in a single value.\"","teach":[{"title":"Mean (the average)","body":"The mean is found by adding up all the values and dividing by how many values there are. It gives a single number that represents the 'typical' value in a dataset.","visual":"➗"},{"title":"Median (the middle value)","body":"The median is the middle value when data is arranged in order from smallest to largest. If there are two middle values, the median is their average.","visual":"🎯"},{"title":"Mode (the most common value)","body":"The mode is the value that appears most often in a dataset. A dataset can have one mode, more than one mode, or no mode at all.","visual":"🔁"}],"questions":[{"kind":"numeric","prompt":"Find the mean of these test scores: 12, 15, 18, 15, 20","answer":16,"explain":"12+15+18+15+20 = 80, and 80 / 5 = 16."},{"kind":"numeric","prompt":"Find the median of these test scores: 12, 15, 18, 15, 20 (arrange in order first)","answer":15,"explain":"Sorted: 12, 15, 15, 18, 20 — the middle value is 15."},{"kind":"numeric","prompt":"Find the mode of these test scores: 12, 15, 18, 15, 20","answer":15,"explain":"15 appears twice, more than any other value, so it is the mode."},{"kind":"numeric","prompt":"Find the mean of: 4, 7, 9, 10","answer":7.5,"explain":"4+7+9+10 = 30, and 30 / 4 = 7.5."},{"kind":"mcq","prompt":"A dataset has one extremely high outlier value. Which average is usually least affected by it?","options":["Sum","Median","Range","Mean"],"answer":1,"explain":"The median only looks at the middle position, so one extreme value barely changes it, unlike the mean."}]},{"id":"ma7","title":"Probability & Types of Events","icon":"🎲","kind":"lesson","story":"A mysterious dealer in the Chance Chamber shuffles cards, flips coins, and rolls dice, daring you to predict the outcome. \"Nothing is certain here,\" she smirks, \"except the math of probability.\"","teach":[{"title":"What is probability?","body":"Probability measures how likely an event is to happen. It is calculated as: Probability = (number of favourable outcomes) / (total number of possible outcomes). It is always a number between 0 and 1.","visual":"🎯"},{"title":"Types of events","body":"An impossible event can never happen (probability 0), like rolling a 7 on a normal die. A certain event will always happen (probability 1), like rolling a number from 1 to 6 on that same die. Events in between are simply more or less likely.","visual":"🔀"}],"questions":[{"kind":"mcq","prompt":"Rolling a 7 on a standard six-sided die is an example of a(n) ___ event.","options":["Impossible","Likely","Certain","Guaranteed"],"answer":0,"explain":"A standard die only has faces 1 to 6, so rolling a 7 can never happen — it is impossible."},{"kind":"numeric","prompt":"A coin is flipped once. What is the probability of getting heads? (Give your answer as a decimal.)","answer":0.5,"explain":"There is 1 favourable outcome (heads) out of 2 possible outcomes, so 1/2 = 0.5."},{"kind":"numeric","prompt":"A standard deck of 52 playing cards is shuffled. What is the probability of drawing a heart? (There are 13 hearts. Give your answer as a decimal.)","answer":0.25,"explain":"13 hearts out of 52 cards: 13/52 = 0.25."},{"kind":"numeric","prompt":"A box contains 4 red balls and 4 blue balls. What is the probability of picking a red ball at random? (Give your answer as a decimal.)","answer":0.5,"explain":"4 red balls out of 8 total balls: 4/8 = 0.5."},{"kind":"mcq","prompt":"Rolling a standard die and getting a number between 1 and 6 (inclusive) is an example of a(n) ___ event.","options":["Certain","Unlikely","Impossible","Rare"],"answer":0,"explain":"Every face of the die shows a number from 1 to 6, so this outcome is guaranteed to happen — it is certain."}]},{"id":"ma8","title":"Probability at Work: Sports, Weather & Traffic","icon":"🌦️","kind":"lesson","story":"At the Forecast Tower, screens flicker between football scores, storm clouds, and highway cameras. The Atlas Guide points out that probability quietly powers predictions in all three.","teach":[{"title":"Probability in weather forecasting","body":"When a weather report says '70% chance of rain', it means that based on past weather data, rain happened 70 times out of 100 similar days — a high probability, but not a certainty.","visual":"🌧️"},{"title":"Probability in sports","body":"Analysts use a team's past results to estimate the probability of winning the next match — the better their recent record, the higher the estimated probability of victory.","visual":"⚽"},{"title":"Probability in traffic estimation","body":"Traffic systems study past congestion data to estimate the probability of heavy traffic on a route at a certain time, helping drivers and city planners plan ahead.","visual":"🚦"}],"questions":[{"kind":"mcq","prompt":"A weather app shows '70% chance of rain today'. What does this mean?","options":["The app is broken","It will definitely rain","Based on past weather data, there is a high probability it will rain","It will definitely not rain"],"answer":2,"explain":"A percentage chance of rain is a probability estimate based on historical weather patterns, not a guarantee."},{"kind":"numeric","prompt":"A weather app says there is a 40% chance of rain today. Written as a decimal, what is this probability?","answer":0.4,"explain":"40% means 40 out of 100, which as a decimal is 0.4."},{"kind":"numeric","prompt":"In the last 10 matches, a football team won 7. Based on this data, what is the probability they win their next match? (Give your answer as a decimal.)","answer":0.7,"explain":"7 wins out of 10 matches: 7/10 = 0.7."},{"kind":"mcq","prompt":"City planners study which routes are congested most often at 6 PM to warn commuters in advance. This is an example of probability applied to ___","options":["Disease prediction","Traffic estimation","Weather forecasting","Sports coaching"],"answer":1,"explain":"Estimating congestion likelihood from past traffic data is exactly what traffic estimation means."},{"kind":"numeric","prompt":"Out of the last 20 days, traffic on a highway was heavy on 5 of the days. What is the probability that traffic will be heavy on a randomly chosen day, based on this data? (Give your answer as a decimal.)","answer":0.25,"explain":"5 heavy-traffic days out of 20 days: 5/20 = 0.25."}]},{"id":"ma-boss","title":"Boss: The Data Dragon","icon":"🐉","kind":"boss","story":"At the peak of the Number Nebula, the Data Dragon coils around a mountain of scrambled statistics and probability puzzles. To pass, you must prove you can find patterns, summarise data, and calculate probability — all under pressure.","teach":[{"title":"Final review","body":"Before the fight: remember mean = sum divided by count, median = the middle sorted value, mode = the most frequent value, and probability = favourable outcomes divided by total outcomes.","visual":"🛡️"}],"questions":[{"kind":"numeric","prompt":"Find the mean of: 5, 10, 15, 20, 25","answer":15,"explain":"5+10+15+20+25 = 75, and 75 / 5 = 15."},{"kind":"numeric","prompt":"Find the median of: 8, 3, 10, 3, 6 (arrange in order first)","answer":6,"explain":"Sorted: 3, 3, 6, 8, 10 — the middle value is 6."},{"kind":"numeric","prompt":"Find the mode of: 2, 4, 4, 6, 8, 4, 2","answer":4,"explain":"4 appears three times, more than any other value, so it is the mode."},{"kind":"numeric","prompt":"Find the missing number in the pattern: 3, 6, 12, 24, ___","answer":48,"explain":"The pattern doubles each time: 24 x 2 = 48."},{"kind":"numeric","prompt":"A standard deck of 52 cards is shuffled. What is the probability of drawing a spade? (There are 13 spades. Give your answer as a decimal.)","answer":0.25,"explain":"13 spades out of 52 cards: 13/52 = 0.25."},{"kind":"mcq","prompt":"Rolling a standard die and getting an 8 is what type of event?","options":["Certain event","Common event","Impossible event","Likely event"],"answer":2,"explain":"A standard die has no face showing 8, so this event can never happen."},{"kind":"mcq","prompt":"Which branch of math is most directly about measuring 'how likely' something is?","options":["Probability","Geometry","Statistics","Algebra"],"answer":0,"explain":"Probability is the branch of math dedicated to measuring likelihood."},{"kind":"mcq","prompt":"A team analysing flood data from the past 50 years to prepare for future floods is applying statistics to ___","options":["Fashion design","Cooking","Music composition","Disaster management"],"answer":3,"explain":"Using historical data to prepare for and predict disasters is the disaster-management application of statistics."}],"boss":{"name":"The Data Dragon","taunt":"Ha! Numbers are my scales and probability is my breath — think you can out-calculate ME?"}}]},{"id":"introgenai9","index":3,"name":"Introduction to Generative AI","subtitle":"Artificial Intelligence — Unit 4","emoji":"✨","palette":{"from":"#a78bfa","to":"#4c1d95"},"lessons":[{"id":"ga1","title":"What Is Generative AI?","icon":"✨","kind":"lesson","story":"You step through a shimmering portal into the Atlas of Ideas, a realm where machines dream up pictures, stories, and songs that never existed before. A floating guide named Pixel greets you: to explore further, you must first learn what makes this land 'generative'.","teach":[{"title":"Generative AI = 'AI That Creates'","body":"Generative AI is a branch of AI that creates brand-new content — text, images, audio, video, or code — instead of just analyzing or sorting existing data. It generates something original each time you ask it to.","visual":"✨"},{"title":"Learns Patterns, Then Creates","body":"It studies huge amounts of existing content, like millions of photos or sentences, to learn patterns, styles, and structures. Then it uses those learned patterns to produce new output that follows similar patterns.","visual":"🧩"},{"title":"Kinds of Generative AI","body":"Generative AI can be classified by what it creates: text generators that write, image generators that draw, audio and music generators, video generators, and code generators.","visual":"🗂️"}],"questions":[{"kind":"mcq","prompt":"What best defines Generative AI?","options":["AI that only recognizes faces in photos","AI that only detects spam messages","AI that only sorts emails into folders","AI that creates new content like text, images, or music"],"answer":3,"explain":"Generative AI's defining feature is generating new, original content rather than just classifying existing data."},{"kind":"mcq","prompt":"Which of these is a way to classify kinds of Generative AI?","options":["By the type of content it generates, like text, image, or audio","By how expensive the computer is","By the color of the app's icon","By the brand of keyboard used"],"answer":0,"explain":"Generative AI is commonly classified by output type: text, image, audio, video, or code."},{"kind":"mcq","prompt":"Generative AI produces new content by...","options":["copying and pasting one existing file exactly","randomly guessing with no training at all","using patterns learned from large amounts of existing data","only following a fixed list of pre-written answers"],"answer":2,"explain":"It learns patterns from training data and uses them to generate new, original outputs."}]},{"id":"ga2","title":"Generative AI vs Conventional AI","icon":"🔀","kind":"lesson","story":"Deeper in the Atlas, you find two glowing doors guarded by a robot: one marked 'PREDICT', the other 'CREATE'. The guardian won't let you pass until you can explain what really separates them.","teach":[{"title":"Conventional AI Predicts or Classifies","body":"Conventional, or predictive, AI is trained to recognize patterns and make decisions about existing data, like predicting tomorrow's weather or labeling an email as spam. It doesn't invent new content.","visual":"📊"},{"title":"Generative AI Creates New Content","body":"Generative AI goes a step further: instead of just labeling or predicting, it produces brand-new text, images, or sounds that didn't exist before, based on what it learned.","visual":"🎨"},{"title":"Same Roots, Different Goals","body":"Both types of AI learn from data, but conventional AI's goal is analysis or prediction, while generative AI's goal is creating original output.","visual":"🧭"}],"questions":[{"kind":"mcq","prompt":"A spam filter that labels email as 'spam' or 'not spam' is an example of...","options":["Conventional (predictive) AI","Generative AI","Neither type of AI","A type of computer hardware"],"answer":0,"explain":"It classifies existing input rather than creating new content, so it is conventional AI."},{"kind":"mcq","prompt":"What is the key difference between Generative AI and Conventional AI?","options":["There is no real difference between them","Generative AI creates new content; conventional AI predicts or classifies existing data","Generative AI is slower at every single task","Conventional AI can only run on phones"],"answer":1,"explain":"Generative AI produces original new content, while conventional AI focuses on prediction and classification."},{"kind":"mcq","prompt":"An AI tool that writes a brand-new poem about your school is an example of...","options":["Conventional AI","A search engine only","Generative AI","A simple calculator"],"answer":2,"explain":"Writing an original poem means creating new content, which is what generative AI does."},{"kind":"mcq","prompt":"Which task best shows conventional, predictive AI at work?","options":["Composing a brand-new song","Predicting whether tomorrow will be rainy or sunny","Writing a brand-new short story","Painting an original picture of a dragon"],"answer":1,"explain":"Predicting weather uses existing data to forecast an outcome, which is a conventional AI task."}]},{"id":"ga3","title":"How Generative AI Learns","icon":"🧠","kind":"lesson","story":"You enter a workshop where a giant loom weaves glowing threads of data into new patterns. The weaver explains that this is how generative AI turns old data into new creations.","teach":[{"title":"Trained on Huge Datasets","body":"Generative AI models are trained on massive collections of existing content, like billions of sentences or millions of images, so they can learn the patterns, styles, and rules hidden within that data.","visual":"📚"},{"title":"Finding Patterns, Not Memorizing","body":"During training, the model adjusts its internal settings to recognize relationships, such as which words usually follow other words, or which shapes usually appear together in a picture.","visual":"🔍"},{"title":"Generating Something New","body":"Once trained, when you give it a prompt, the model uses those learned patterns to build new content step-by-step, combining ideas in fresh ways rather than copying one exact source.","visual":"⚙️"}],"questions":[{"kind":"mcq","prompt":"How does a generative AI model learn to create content?","options":["By asking a teacher for the answer key","By flipping a coin for every decision","By memorizing one single photo forever","By studying patterns in large amounts of existing data during training"],"answer":3,"explain":"Generative AI models learn patterns from large training datasets."},{"kind":"mcq","prompt":"What happens after a generative AI model finishes training?","options":["It stops working and needs replacing","It automatically becomes a conventional predictive AI","It deletes all the data it studied","It uses the patterns it learned to generate new content from a prompt"],"answer":3,"explain":"After training, the model applies its learned patterns to generate new content when prompted."},{"kind":"mcq","prompt":"Why does generative AI need very large amounts of training data?","options":["So it can store everyone's personal photos forever","Because bigger files always look nicer on screen","So it can learn enough patterns and variety to create convincing new content","Because small datasets make the software crash instantly"],"answer":2,"explain":"More varied training data helps the model learn richer patterns, improving the quality of what it generates."}]},{"id":"ga4","title":"Types of Generative AI","icon":"🗂️","kind":"lesson","story":"A hall of five glowing portals stretches before you, each humming with a different kind of creative power. You must match each portal to the kind of content it generates.","teach":[{"title":"Text Generators","body":"These models generate written content, like answering questions, writing stories, or summarizing text, by predicting the next most likely word based on patterns learned from huge amounts of text.","visual":"📝"},{"title":"Image & Video Generators","body":"These create pictures or video clips from a text description, learning from millions of images how colors, shapes, and objects usually go together.","visual":"🖼️"},{"title":"Audio, Music & Code Generators","body":"Some generative AI creates music or realistic speech, while others generate programming code by learning patterns from existing code written by programmers.","visual":"🎵"}],"questions":[{"kind":"mcq","prompt":"A tool that turns the text prompt 'a cat wearing a hat' into a brand-new picture is a...","options":["Text generator","Search engine","Image generator","Spam filter"],"answer":2,"explain":"Turning a text prompt into a new picture is exactly what an image generator does."},{"kind":"mcq","prompt":"Which is an example of a text-generating task?","options":["Detecting whether a picture has a cat in it","Sorting files by their size","Measuring your typing speed","Writing an original paragraph that answers a question"],"answer":3,"explain":"Writing new original text is the core job of a text generator."},{"kind":"mcq","prompt":"Generative AI that writes new programming code based on patterns from existing code is called a...","options":["Weather predictor","Code generator","Image classifier","Spam detector"],"answer":1,"explain":"A code generator learns from existing code to produce new code."},{"kind":"mcq","prompt":"Which type of generative AI would you use to create a brand-new song?","options":["A barcode scanner","An audio or music generator","A text generator only","A spam filter"],"answer":1,"explain":"Music generators are a type of generative AI trained to create new audio and music."}]},{"id":"ga5","title":"Real Examples & Tools","icon":"🧰","kind":"lesson","story":"In the Atlas marketplace, friendly tool merchants show off their wares: a chatty scribe, a painting machine, and a code-writing helper. Time to learn which real-world tools they represent.","teach":[{"title":"Text & Chat Tools","body":"Tools like ChatGPT and Claude are generative AI chatbots that can answer questions, write essays, and hold conversations by generating new text responses.","visual":"💬"},{"title":"Image-Generating Tools","body":"Tools like DALL·E and Midjourney can turn a written description into an original picture or artwork in seconds.","visual":"🎨"},{"title":"Other Everyday Generative Tools","body":"Other examples include AI music generators, AI voice generators, and AI coding assistants like GitHub Copilot, which suggests new lines of code as you type.","visual":"💻"}],"questions":[{"kind":"mcq","prompt":"Which of these is a real example of a generative AI chatbot?","options":["A plain web browser bookmark","A calculator app","ChatGPT","A paper dictionary"],"answer":2,"explain":"ChatGPT is a well-known generative AI chatbot that creates new text responses."},{"kind":"mcq","prompt":"Which tool is known for generating new images from text descriptions?","options":["A file compression tool","A spreadsheet program","DALL·E","A digital photo album app"],"answer":2,"explain":"DALL·E is a generative AI tool that creates original images from text prompts."},{"kind":"mcq","prompt":"GitHub Copilot is a generative AI tool that mainly helps with...","options":["Predicting tomorrow's weather","Sorting emails into folders","Suggesting and generating programming code","Scanning documents for viruses"],"answer":2,"explain":"GitHub Copilot generates new lines of code based on patterns learned from existing code."}]},{"id":"ga6","title":"Benefits of Generative AI","icon":"🚀","kind":"lesson","story":"You wander into a glowing garden where every fruit represents a benefit of Generative AI. Picking one lets you feel its power to save time and spark new ideas.","teach":[{"title":"Saves Time & Boosts Creativity","body":"Generative AI can quickly draft essays, images, or ideas, helping people brainstorm and get started faster, and can spark new creative directions they might not have thought of.","visual":"⚡"},{"title":"Personalized & Accessible Help","body":"It can assist with tasks like tutoring, translating languages, or drafting messages, making some kinds of help more accessible to more people.","visual":"🌍"},{"title":"Useful Across Many Fields","body":"From designers making artwork to students summarizing notes to businesses creating marketing content, generative AI supports many different kinds of work.","visual":"🏫"}],"questions":[{"kind":"mcq","prompt":"Which of the following is a genuine benefit of Generative AI?","options":["It can help people brainstorm ideas and create drafts quickly","It completely replaces the need for human creativity","It always produces perfectly true facts with zero errors","It never needs any training data"],"answer":0,"explain":"A real benefit is speeding up brainstorming and drafting, not guaranteed perfect accuracy."},{"kind":"mcq","prompt":"How can generative AI help a student?","options":["By automatically taking their exams for them","By deleting their homework files","By permanently replacing their teacher","By helping summarize notes or explain a topic in a new way"],"answer":3,"explain":"Generative AI can support learning, such as by summarizing or re-explaining material."},{"kind":"mcq","prompt":"Why might a business use generative AI tools?","options":["To permanently replace all of its human employees","To quickly create drafts of marketing content or images","To make their computers run slower","To avoid ever needing customer feedback"],"answer":1,"explain":"Businesses often use generative AI to speed up creating drafts of content like marketing copy or images."}]},{"id":"ga7","title":"Limitations of Generative AI","icon":"⚖️","kind":"lesson","story":"The path leads into a dim cave where shadows whisper false facts. This is where you learn that even powerful generative AI has real weaknesses you must watch out for.","teach":[{"title":"Can Be Wrong or Made Up","body":"Generative AI can produce 'hallucinations', confident-sounding but false or made-up information, because it is predicting patterns rather than checking verified facts.","visual":"❓"},{"title":"Reflects Bias in Training Data","body":"If the data used to train it contains biases or mistakes, the content it generates can repeat or amplify those same biases.","visual":"⚠️"},{"title":"Needs Resources & Human Judgment","body":"Training and running generative AI models require large amounts of computing power and energy, and their output still needs to be checked by humans before being trusted or used.","visual":"🔋"}],"questions":[{"kind":"mcq","prompt":"What is it called when generative AI confidently produces false or made-up information?","options":["A hallucination","A cache","A firewall","A cookie"],"answer":0,"explain":"A 'hallucination' is when generative AI confidently states something false or made up."},{"kind":"mcq","prompt":"Why can generative AI output be biased?","options":["Because it only works on Mondays","Because it has no connection to any data","Because it learns patterns from training data, which may itself contain biases","Because it refuses to generate any content at all"],"answer":2,"explain":"Bias in training data can carry over into the patterns the model learns and generates."},{"kind":"mcq","prompt":"Why should people always double-check what generative AI creates?","options":["Because it never works on phones","Because using generative AI is illegal","Because it always costs a lot of money","Because it can make mistakes or produce inaccurate information"],"answer":3,"explain":"Since generative AI can be inaccurate, humans should verify its output before trusting or sharing it."}]},{"id":"ga-boss","title":"Boss: Mirage, the Shapeshifter","icon":"🎭","kind":"boss","story":"At the heart of the Atlas of Ideas waits Mirage, a shapeshifting trickster who creates fake images, false stories, and copied art to confuse travelers. Only by mastering the ethics of Generative AI can you see through every illusion.","teach":[{"title":"Deepfakes Can Deceive","body":"Deepfakes are realistic fake images, videos, or audio created by generative AI that can make it look like someone said or did something they never actually did, which can be used to trick or harm people.","visual":"🎭"},{"title":"Misinformation Spreads Fast","body":"Because generative AI can create convincing false text or images very quickly, it can be misused to spread misinformation, so it is important to verify information from trusted sources.","visual":"📰"},{"title":"Copyright & Over-Reliance","body":"Generative AI is trained on existing creative work, which raises copyright questions about crediting original creators. Relying on it too much without thinking for yourself can also weaken your own skills and judgment.","visual":"©️"}],"boss":{"name":"Mirage, the Shapeshifter","taunt":"You'll never tell my fakes from the real thing... or will you?"},"questions":[{"kind":"mcq","prompt":"What is a 'deepfake'?","options":["A backup copy of a file","A realistic fake image, video, or audio made by AI to look real","A type of computer virus","A kind of computer keyboard"],"answer":1,"explain":"A deepfake is AI-generated fake media designed to look convincingly real."},{"kind":"mcq","prompt":"Why are deepfakes considered an ethical risk of Generative AI?","options":["They are only ever used for fixing typos","They make computers run faster","They can deceive people into believing something false actually happened","They always come clearly labeled as fake"],"answer":2,"explain":"Deepfakes can mislead people by making fabricated events look real."},{"kind":"mcq","prompt":"Which best describes the copyright concern with Generative AI?","options":["AI models learn from existing creative works, raising questions about crediting original creators","Copyright issues stopped existing after AI was invented","Generative AI never uses any existing data","AI-generated content can never be shared with anyone"],"answer":0,"explain":"Since models train on existing creative work, questions arise about giving proper credit to original creators."},{"kind":"mcq","prompt":"What does 'over-reliance' on Generative AI mean?","options":["Depending on AI so much that it weakens your own thinking and skills","Using AI exactly once a year","Never using any AI tools at all","Reading only printed books"],"answer":0,"explain":"Over-reliance means leaning on AI so heavily that you stop developing your own abilities."},{"kind":"mcq","prompt":"Generative AI creates new content by learning patterns from data. Conventional AI, by contrast, mainly...","options":["Writes original novels","Predicts or classifies based on existing data","Composes brand-new symphonies","Generates brand-new artwork"],"answer":1,"explain":"Conventional AI focuses on prediction and classification rather than creating new content."},{"kind":"mcq","prompt":"Which is a responsible way to use Generative AI output?","options":["Use it to impersonate real people without their consent","Share everything instantly without checking it","Double-check facts and give credit where needed","Assume it is always 100% correct"],"answer":2,"explain":"Responsible use means verifying accuracy and respecting original creators."},{"kind":"mcq","prompt":"Which of these is a real example of a Generative AI tool?","options":["A traditional thermostat","ChatGPT, a generative AI chatbot","A paper map","A pocket calculator"],"answer":1,"explain":"ChatGPT is a widely known generative AI chatbot."},{"kind":"mcq","prompt":"Misinformation created by Generative AI is a concern mainly because...","options":["It cannot be created quickly","It only affects computers, not people","Convincing false content can spread quickly and mislead people","It makes the internet load faster"],"answer":2,"explain":"Generative AI can rapidly create realistic false content, which can spread and mislead people."}]}]},{"id":"intropython9","index":4,"name":"Introduction to Python","subtitle":"Artificial Intelligence — Unit 5","emoji":"🐍","palette":{"from":"#facc15","to":"#713f12"},"lessons":[{"id":"py1","title":"Variables & Data Types","icon":"📦","kind":"lesson","story":"The final gate of the Study Atlas shimmers into view: the Py-thon Sanctuary. A soft voice hisses, 'To enter, you must learn to store knowledge itself — in variables.'","teach":[{"title":"Variables","body":"A variable is a named box that stores a value in memory. In Python you create one simply by assigning a value with =, like name = \"Aria\" — there's no need to declare a type first.","visual":"📦"},{"title":"Data Types","body":"Python automatically figures out the data type. age = 14 is a whole number (int), height = 5.6 is a decimal number (float), and city = \"Delhi\" is text (str).","visual":"🔤"},{"title":"The print() Function","body":"print() displays output on the screen. print(\"Hello\") shows Hello, and you can print several values separated by commas: print(\"Age:\", age).","visual":"🖨️"}],"questions":[{"kind":"mcq","prompt":"Which of these is a valid Python variable assignment?","options":["score = 100","score := 100 = x","int score = 100","100 = score"],"answer":0,"explain":"In Python you write variable_name = value. A number can't sit on the left side, and unlike some languages, you never write a type keyword like int before the name."},{"kind":"mcq","prompt":"What does this print?\nname = \"Rohan\"\nprint(name)","options":["\"Rohan\"","Error","Rohan","name"],"answer":2,"explain":"print(name) shows the VALUE stored in the variable name, which is the text Rohan — not the word 'name' and not the quote marks."},{"kind":"mcq","prompt":"What is the data type of the value 5.6 in Python?","options":["str","float","bool","int"],"answer":1,"explain":"Any number written with a decimal point, like 5.6, is a float in Python."},{"kind":"mcq","prompt":"Which function is used to display output on the screen in Python?","options":["output()","input()","print()","display()"],"answer":2,"explain":"print() is the built-in function used to show text or values on the screen."}]},{"id":"py2","title":"input() and Type Conversion","icon":"⌨️","kind":"lesson","story":"A stone door asks you a question and waits. You realize the Sanctuary wants you to talk back to your program — and to convert its answers into numbers it can use.","teach":[{"title":"The input() Function","body":"input() pauses the program and waits for the user to type something, then hands that text back to your program: name = input(\"Enter your name: \").","visual":"⌨️"},{"title":"input() Always Gives Text","body":"Even if the user types a number, input() always returns it as a string. Typing 7 gives you the text \"7\", not the number 7 — so 'age' from input() can't be used in maths yet.","visual":"❓"},{"title":"Type Conversion","body":"Use int() to convert text into a whole number, and float() to convert it into a decimal number: age = int(input(\"Enter age: \")). You can also use str() to turn a number into text.","visual":"🔁"}],"questions":[{"kind":"mcq","prompt":"What data type does input() always return, before any conversion?","options":["bool","float","str (string)","int"],"answer":2,"explain":"input() always hands back the user's typing as text (a string), no matter what characters were typed."},{"kind":"mcq","prompt":"A program runs this code, and the user types 7:\nx = input()\ny = int(x) + 3\nprint(y)\nWhat does it print?","options":["73","Error","7 3","10"],"answer":3,"explain":"x becomes the string \"7\". int(x) converts it to the number 7, and 7 + 3 = 10."},{"kind":"mcq","prompt":"Which function converts a string like \"12\" into a whole number?","options":["float()","str()","int()","input()"],"answer":2,"explain":"int() converts text made of digits into a whole number so it can be used in arithmetic."},{"kind":"mcq","prompt":"What does this print?\nnum = \"5\"\nprint(int(num) + int(num))","options":["5 5","Error","10","55"],"answer":2,"explain":"int(\"5\") gives the number 5 both times, so 5 + 5 = 10."}]},{"id":"py3","title":"Arithmetic Operators & Expressions","icon":"🧮","kind":"lesson","story":"Glowing runes cover the sanctuary floor: +, -, *, /, and stranger symbols. They rearrange themselves into sums, waiting for you to calculate their true value.","teach":[{"title":"Basic Arithmetic","body":"Python supports + (add), - (subtract), * (multiply), and / (divide). Division with / always gives a float result, even when it divides evenly: 10 / 2 gives 5.0.","visual":"➕"},{"title":"// and %","body":"// is floor division — it divides and drops any remainder, giving a whole number: 17 // 5 gives 3. % is the modulus operator, giving only the remainder: 17 % 5 gives 2.","visual":"➗"},{"title":"** and Expressions","body":"** raises a number to a power: 2 ** 3 means 2×2×2 = 8. An expression is any mix of values and operators, evaluated using the usual order of operations (BODMAS): 2 + 3 * 4 gives 14, not 20.","visual":"🔺"}],"questions":[{"kind":"numeric","prompt":"What does this print?\nprint(7 + 3 * 2)","answer":13,"explain":"By BODMAS, multiplication happens first: 3 * 2 = 6, then 7 + 6 = 13."},{"kind":"numeric","prompt":"What does this print?\nprint(17 // 5)","answer":3,"explain":"17 // 5 is floor division: 5 fits into 17 three times (15), so the result is 3, dropping the remainder."},{"kind":"numeric","prompt":"What does this print?\nprint(17 % 5)","answer":2,"explain":"% gives only the remainder: 17 divided by 5 is 3 remainder 2, so the answer is 2."},{"kind":"numeric","prompt":"What does this print?\nprint(2 ** 4)","answer":16,"explain":"** is the power operator: 2 ** 4 means 2×2×2×2 = 16."},{"kind":"mcq","prompt":"What does the / operator always return in Python, even when the division is exact?","options":["A float (decimal) value","A string value","An integer value","An error"],"answer":0,"explain":"In Python 3, / always produces a float — for example 10 / 2 is 5.0, not 5. Use // if you want a whole-number result."}]},{"id":"py4","title":"Comparison Operators","icon":"⚖️","kind":"lesson","story":"A pair of stone scales blocks your path. They only lower when you can correctly weigh two values against each other — truthfully answering True or False.","teach":[{"title":"Comparing Values","body":"Comparison operators — == (equal to), != (not equal to), >, <, >=, <= — compare two values and always produce a Boolean result: True or False. For example, 5 > 3 evaluates to True.","visual":"⚖️"},{"title":"= vs ==","body":"Don't confuse = (assignment, stores a value) with == (comparison, checks equality). x = 5 stores 5 in x; x == 5 asks 'is x equal to 5?' and gives True or False.","visual":"🟰"},{"title":"Why It Matters","body":"Comparisons are the building blocks of decisions in code, like checking whether marks are high enough to pass: marks >= 40.","visual":"✅"}],"questions":[{"kind":"mcq","prompt":"What does this print?\nprint(10 > 7)","options":["True","Error","False","10"],"answer":0,"explain":"10 is greater than 7, so the comparison evaluates to True."},{"kind":"mcq","prompt":"What does this print?\nprint(5 == 5.0)","options":["Error","True","False","None"],"answer":1,"explain":"Python compares the numeric value, not the type, so the int 5 and the float 5.0 are considered equal — this prints True."},{"kind":"mcq","prompt":"What does this print?\nprint(8 != 8)","options":["Error","8","False","True"],"answer":2,"explain":"!= means 'not equal to'. Since 8 is equal to 8, 'not equal' is False."},{"kind":"mcq","prompt":"Which symbol checks whether two values are equal, without changing anything?","options":["!=","<>","=","=="],"answer":3,"explain":"== is the comparison (equality) operator. A single = is assignment, and it stores a value instead of comparing."}]},{"id":"py5","title":"Logical Operators","icon":"🔗","kind":"lesson","story":"Two levers, marked AND and OR, and a switch marked NOT sit before a locked archway. You'll need to combine conditions correctly to make it open.","teach":[{"title":"and","body":"and gives True only when BOTH conditions are True. age >= 13 and age <= 19 checks whether someone is a teenager — both parts must hold.","visual":"🔗"},{"title":"or","body":"or gives True when AT LEAST ONE condition is True. is_saturday or is_sunday checks for a weekend — only one needs to be true.","visual":"🔀"},{"title":"not","body":"not flips a Boolean value: not True becomes False, and not False becomes True.","visual":"🚫"}],"questions":[{"kind":"mcq","prompt":"What does this print?\nprint(5 > 2 and 3 > 10)","options":["Error","5","True","False"],"answer":3,"explain":"5 > 2 is True, but 3 > 10 is False. Since and needs BOTH to be True, the result is False."},{"kind":"mcq","prompt":"What does this print?\nprint(5 > 2 or 3 > 10)","options":["3","Error","True","False"],"answer":2,"explain":"5 > 2 is True. Since or only needs ONE condition to be True, the whole expression is True."},{"kind":"mcq","prompt":"What does this print?\nprint(not(5 > 2))","options":["False","Error","5","True"],"answer":0,"explain":"5 > 2 is True, and not flips it to False."},{"kind":"mcq","prompt":"Which operator gives True only when BOTH conditions are True?","options":["or","not","==","and"],"answer":3,"explain":"and requires every condition joined by it to be True for the whole expression to be True."}]},{"id":"py6","title":"Assignment Operators","icon":"🔄","kind":"lesson","story":"A counter etched into the wall keeps ticking. To keep pace with it, you'll need faster ways to update a variable's value.","teach":[{"title":"Basic Assignment","body":"= stores a value in a variable: x = 10 puts the number 10 into x. This is the simplest assignment operator.","visual":"🟰"},{"title":"Compound Assignment","body":"Shortcut operators combine an operation with assignment. x += 5 means the same as x = x + 5 — it adds 5 to x and stores the result back into x.","visual":"➕"},{"title":"More Shortcuts","body":"Likewise, x -= 2 subtracts 2 from x, x *= 3 multiplies x by 3, and x /= 2 divides x by 2 — each one updates the variable itself with the new result.","visual":"🔁"}],"questions":[{"kind":"numeric","prompt":"What does this print?\nx = 10\nx += 5\nprint(x)","answer":15,"explain":"x += 5 means x = x + 5, so 10 + 5 = 15."},{"kind":"numeric","prompt":"What does this print?\nx = 20\nx -= 8\nprint(x)","answer":12,"explain":"x -= 8 means x = x - 8, so 20 - 8 = 12."},{"kind":"numeric","prompt":"What does this print?\nx = 4\nx *= 3\nprint(x)","answer":12,"explain":"x *= 3 means x = x * 3, so 4 * 3 = 12."},{"kind":"mcq","prompt":"What does x += 1 do?","options":["Compares x to 1","Adds 1 to x and stores the result back in x","Creates a new variable called x1","Prints x plus 1 without changing x"],"answer":1,"explain":"+= is a compound assignment operator: it computes x + 1 and saves that new value back into x."}]},{"id":"py7","title":"Flow of Control: if / elif / else","icon":"🚦","kind":"lesson","story":"A fork in the Sanctuary's path splits into three glowing trails. Only your code's decisions can choose which one you walk.","teach":[{"title":"The if Statement","body":"An if statement runs a block of code only when its condition is True. Python uses indentation (spaces) to mark which lines belong inside the block:\nif age >= 18:\n    print(\"Adult\")","visual":"🚦"},{"title":"else","body":"The else block runs when the if condition turns out False, giving your program a fallback action to take instead.","visual":"🔀"},{"title":"elif","body":"elif (short for 'else if') checks another condition when the earlier ones were False. Python checks each one in order and runs only the FIRST block whose condition is True.","visual":"🪜"}],"questions":[{"kind":"mcq","prompt":"What does this print?\nage = 20\nif age >= 18:\n    print(\"Adult\")\nelse:\n    print(\"Minor\")","options":["Adult","20","Minor","Error"],"answer":0,"explain":"age (20) is greater than or equal to 18, so the if condition is True and \"Adult\" is printed."},{"kind":"mcq","prompt":"What does this print?\nmarks = 55\nif marks >= 90:\n    print(\"A\")\nelif marks >= 60:\n    print(\"B\")\nelif marks >= 40:\n    print(\"C\")\nelse:\n    print(\"D\")","options":["B","D","A","C"],"answer":3,"explain":"55 >= 90 is False, 55 >= 60 is False, but 55 >= 40 is True, so \"C\" is printed and the rest are skipped."},{"kind":"mcq","prompt":"What does this print?\nnum = 0\nif num > 0:\n    print(\"Positive\")\nelif num < 0:\n    print(\"Negative\")\nelse:\n    print(\"Zero\")","options":["Negative","0","Positive","Zero"],"answer":3,"explain":"num (0) is not greater than 0 and not less than 0, so neither if nor elif runs — the else block prints \"Zero\"."},{"kind":"mcq","prompt":"In one pass through an if/elif/else chain, how many of its blocks can run?","options":["None, ever","Always exactly two","All the matching blocks","At most one"],"answer":3,"explain":"Python checks the conditions in order and runs only the first block that is True, then skips the rest of the chain."}]},{"id":"py8","title":"Flow of Control: for and while Loops","icon":"🔁","kind":"lesson","story":"A spinning wheel of runes refuses to stop turning. To pass, you must predict exactly how many times it will spin before it halts.","teach":[{"title":"for Loops with range()","body":"A for loop repeats a block a set number of times. for i in range(5): repeats 5 times, with i taking the values 0, 1, 2, 3, 4 — range(5) generates 5 numbers starting at 0.","visual":"🔁"},{"title":"while Loops","body":"A while loop repeats as long as its condition stays True. You must update the variable inside the loop, or it will run forever (an infinite loop):\ni = 0\nwhile i < 3:\n    print(i)\n    i += 1","visual":"⏳"},{"title":"for vs while","body":"Use for when you know how many times to repeat (like counting 1 to 10). Use while when you repeat until a condition changes, and you aren't sure in advance exactly how many times that will take.","visual":"🤔"}],"questions":[{"kind":"numeric","prompt":"How many times does this loop run?\nfor i in range(5):\n    print(i)","answer":5,"explain":"range(5) produces exactly 5 values (0, 1, 2, 3, 4), so the loop body runs 5 times."},{"kind":"mcq","prompt":"What is the LAST value of i printed by this loop?\nfor i in range(5):\n    print(i)","options":["3","5","4","0"],"answer":2,"explain":"range(5) counts 0, 1, 2, 3, 4 — it stops before reaching 5, so the last value printed is 4."},{"kind":"numeric","prompt":"How many numbers does this loop print in total?\ni = 1\nwhile i < 4:\n    print(i)\n    i += 1","answer":3,"explain":"The loop prints i while i < 4: it prints 1, then 2, then 3. When i becomes 4, the condition is False and it stops — 3 numbers in all."},{"kind":"numeric","prompt":"What does this print?\ntotal = 0\nfor i in range(1, 4):\n    total += i\nprint(total)","answer":6,"explain":"range(1, 4) gives 1, 2, 3. Adding them into total: 0+1=1, 1+2=3, 3+3=6, so the final printed value is 6."},{"kind":"mcq","prompt":"What could happen if you forget to update the loop variable inside a while loop?","options":["Nothing — Python fixes it automatically","The program shows an error immediately","Python automatically stops it after 10 times","The loop may run forever (an infinite loop)"],"answer":3,"explain":"If the condition never becomes False because the variable never changes, the while loop keeps repeating forever."}]},{"id":"py9","title":"Python Lists","icon":"📋","kind":"lesson","story":"The final chamber holds a long scroll listing every hero who ever crossed the Sanctuary. To read and edit it, you must master the Python list.","teach":[{"title":"Creating Lists and Indexing","body":"A list stores multiple values in one variable, in order, written with square brackets: fruits = [\"apple\", \"banana\", \"cherry\"]. Each item has an index starting at 0, so fruits[0] is \"apple\".","visual":"📋"},{"title":"Negative Indexing and len()","body":"Negative indexes count from the end: fruits[-1] gives the last item, \"cherry\". The function len(fruits) tells you how many items are in the list.","visual":"🔢"},{"title":"append() and extend()","body":"append() adds one item to the end of a list: fruits.append(\"mango\"). extend() adds all items from another list, one by one: fruits.extend([\"kiwi\", \"grapes\"]).","visual":"➕"},{"title":"remove() and sort()","body":"remove() deletes the first matching value from a list: fruits.remove(\"banana\"). sort() rearranges the list in order — alphabetical for strings, smallest-to-largest for numbers.","visual":"🔀"}],"questions":[{"kind":"mcq","prompt":"What does this print?\nnums = [23, 12, 5, 9]\nprint(nums[1])","options":["23","5","9","12"],"answer":3,"explain":"Indexing starts at 0, so nums[0] is 23 and nums[1] is 12."},{"kind":"mcq","prompt":"What does this print?\nnums = [23, 12, 5, 9]\nprint(nums[-1])","options":["5","Error","23","9"],"answer":3,"explain":"Negative index -1 refers to the last item in the list, which is 9."},{"kind":"numeric","prompt":"What does this print?\nnames = [\"Arjun\", \"Sonakshi\", \"Vikram\", \"Sandhya\"]\nprint(len(names))","answer":4,"explain":"len() counts the items in the list. There are 4 names, so it prints 4."},{"kind":"mcq","prompt":"What does this print?\nnums = [10, 20, 30]\nnums.append(40)\nprint(nums)","options":["[40, 10, 20, 30]","Error","[10, 20, 30]","[10, 20, 30, 40]"],"answer":3,"explain":"append() adds the new item, 40, to the END of the list."},{"kind":"mcq","prompt":"What does this print?\nnums = [40, 10, 30, 20]\nnums.sort()\nprint(nums)","options":["[40, 10, 30, 20]","[40, 30, 20, 10]","Error","[10, 20, 30, 40]"],"answer":3,"explain":"sort() rearranges the numbers from smallest to largest by default: [10, 20, 30, 40]."}]},{"id":"py-boss","title":"The Py-thon Overlord","icon":"🐉","kind":"boss","story":"At the heart of the Sanctuary, lines of glowing code coil into a serpent shape. The Py-thon Overlord awakens — the final guardian of your Class 9 AI journey.","teach":[{"title":"Final Review","body":"You've learned variables, data types, operators, input/output, type conversion, if/elif/else, for and while loops, and Python lists. Trace each snippet carefully before you answer — the Overlord rewards patience.","visual":"🐍"}],"boss":{"name":"The Py-thon Overlord","taunt":"Trace my code correctly, young coder, and I might just let you graduate to Class 10 syntax!"},"questions":[{"kind":"mcq","prompt":"What does this print?\nx = 5\ny = 2\nprint(x + y * 2)","options":["7","9","14","10"],"answer":1,"explain":"BODMAS: y * 2 = 4 first, then x + 4 = 5 + 4 = 9."},{"kind":"numeric","prompt":"What does this print?\nprint(9 // 2)","answer":4,"explain":"// is floor division: 2 fits into 9 four times (8), so the result is 4, dropping the remainder."},{"kind":"mcq","prompt":"What does this print?\nage = int(\"15\")\nprint(age + 5)","options":["20","15 5","Error","155"],"answer":0,"explain":"int(\"15\") converts the text into the number 15, and 15 + 5 = 20."},{"kind":"mcq","prompt":"What does this print?\nprint(4 > 2 and 6 < 5)","options":["Error","4","True","False"],"answer":3,"explain":"4 > 2 is True, but 6 < 5 is False. Since and needs both to be True, the result is False."},{"kind":"mcq","prompt":"What does this print?\nmarks = 72\nif marks >= 90:\n    print(\"A\")\nelif marks >= 70:\n    print(\"B\")\nelse:\n    print(\"C\")","options":["A","C","B","Error"],"answer":2,"explain":"72 >= 90 is False, but 72 >= 70 is True, so \"B\" is printed."},{"kind":"numeric","prompt":"How many times does this loop run?\nfor i in range(3, 8):\n    print(i)","answer":5,"explain":"range(3, 8) produces 3, 4, 5, 6, 7 — that's 5 values, so the loop runs 5 times."},{"kind":"mcq","prompt":"What does this print?\nnums = [5, 15, 25]\nnums.append(35)\nprint(nums[-1])","options":["35","5","25","Error"],"answer":0,"explain":"append(35) puts 35 at the end of the list, and nums[-1] refers to that last item, 35."},{"kind":"mcq","prompt":"What does this print?\nscores = [88, 45, 67]\nscores.sort()\nprint(scores[0])","options":["45","88","Error","67"],"answer":0,"explain":"sort() arranges the list ascending: [45, 67, 88]. Index 0 of the sorted list is 45."}]}]}];